(()=>{'use strict';
function paymentDiagnostic(p){const d=p?.diagnostic;if(!d?.message||['done','cash_done','cancelled'].includes(p.state))return null;const box=document.createElement('details'),heading=document.createElement('summary'),message=document.createElement('p');box.dataset.paymentDiagnostic='1';box.open=true;const receipt=d.phase==='receipt'||p.paid,waiting=['payment_waiting','receipt_waiting','payment_sending','receipt_sending','paid'].includes(p.state);heading.textContent=waiting?(receipt?'Проверка чека':'Проверка оплаты'):(receipt?'Почему чек ещё не подтверждён':'Почему оплата остановилась');message.textContent=d.message;box.append(heading,message);const checked=Number(d.checkedAt);if(Number.isFinite(checked)&&checked>0){const when=document.createElement('small');when.textContent='Проверено '+new Date(checked).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'})+' МСК';box.append(when);}return box;}
const el=(tag,text)=>{const e=document.createElement(tag);e.textContent=text??'';return e;},money=n=>(n/100).toLocaleString('ru-RU')+' ₽';
async function api(path,body){const response=await fetch('/api/admin/'+path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await response.json();if(!response.ok)throw Object.assign(Error(d.error||'Нет подтверждения. Обновите данные.'),{status:response.status});return d;}
function modal(title){const d=el('dialog'),h=el('h2',title),body=el('div'),error=el('p'),close=el('button','Закрыть');d.className='guest-dialog';error.setAttribute('role','status');close.type='button';close.onclick=()=>d.close();d.append(h,body,error,close);d.onclose=()=>d.remove();document.body.append(d);d.showModal();return {d,body,error};}
function button(root,label,fn){const b=el('button',label);b.type='button';b.onclick=async()=>{if(b.disabled)return;b.disabled=true;try{await fn();}catch(e){const d=b.closest('dialog');(d?.querySelector('[role=status]')||b.parentNode.appendChild(el('p'))).textContent=e.message;}finally{b.disabled=false;}};root.append(b);return b;}
function confirmCash(message){return new Promise(resolve=>{const m=modal('Подтвердить получение денег');m.body.append(el('p',message));m.d.addEventListener('close',()=>resolve(false));button(m.body,'Да, деньги получены',()=>{resolve(true);m.d.close();});});}
function input(root,label,value=''){const l=el('label',label),i=el('input');i.value=value;l.append(i);root.append(l);return i;}
function cents(value){if(!/^\d+(?:[.,]\d{1,2})?$/.test(value))throw Error('Введите сумму в рублях.');return Math.round(Number(value.replace(',','.'))*100);}
async function choose(){const list=await api('guest-bills');return new Promise(resolve=>{const m=modal('Счёт гостя');m.d.addEventListener('close',()=>resolve(null));for(const b of list.items)if(!b.payment||b.payment.state==='cancelled')button(m.body,b.name+' · '+b.location+' · '+money(b.totalCents),()=>{resolve(b);m.d.close();});m.body.append(el('h3','Новый счёт'));const name=input(m.body,'Имя гостя'),location=input(m.body,'Стол / место'),phone=input(m.body,'Телефон · необязательно'),l=el('div'),deferred=el('input');deferred.type='checkbox';deferred.hidden=true;l.className='guest-payment-choice';l.setAttribute('role','group');l.setAttribute('aria-label','Когда гость оплатит');l.append(el('strong','Когда гость оплатит?'));const options=el('div'),hint=el('p');options.className='guest-payment-options';const before=button(options,'Сначала оплата',()=>selectPayment(false)),later=button(options,'Оплатит позже',()=>selectPayment(true));function selectPayment(value){deferred.checked=value;before.setAttribute('aria-pressed',String(!value));later.setAttribute('aria-pressed',String(value));hint.textContent=value?'Готовим и выдаём сейчас. Счёт останется неоплаченным.':'Готовим и выдаём после оплаты общего счёта.';}selectPayment(false);l.append(options,hint,deferred);m.body.append(l);const requestId=crypto.randomUUID();button(m.body,'Создать счёт',async()=>{const b=await api('guest-bills/create',{requestId,name:name.value,location:location.value,phone:phone.value,deferred:deferred.checked});resolve(b);m.d.close();});});}
async function show(id){const m=modal(id?'Счёт гостя':'Открытые счета гостей');let busy=false,signature='';
 async function draw(){if(busy)return;const data=await api('guest-bills'+(id?'?id='+id:''));const next=JSON.stringify(data);if(next===signature)return;signature=next;m.body.replaceChildren();if(!id){if(!data.items.length)m.body.append(el('p','Неоплаченных счетов нет.'));for(const b of data.items)button(m.body,'№'+b.id+' · '+b.name+' · '+b.location+' · '+money(b.totalCents),()=>{m.d.close();return show(b.id);});button(m.body,'Новый счёт',async()=>{const b=await choose();if(b){m.d.close();await show(b.id);}});return;}
 const b=data;m.body.append(el('h3',b.name+' · '+b.location),el('p',b.cancelled_at?'Счёт отменён':b.paid_at?'Оплачен':b.deferred?'НЕ ОПЛАЧЕНО · оплата позже':'Общий счёт · перед выдачей'),el('strong',(b.cancelled_at?'Сумма отменённого счёта: ':'')+money(b.totalCents)));if(b.cancelled_at)m.body.append(el('p','Оплата не требуется. Позиции и сумма сохранены для истории.'));
 for(const l of b.lines){let title=(l.kind==='cafe'?'Кафе':'Прокат')+' №'+l.source_id;m.body.append(el('p',title+' — '+money(l.amount)));}
 if(b.payment)m.body.append(el('p',b.payment.label));const diagnostic=paymentDiagnostic(b.payment);if(diagnostic)m.body.append(diagnostic);
 if(!b.paid_at&&!b.cancelled_at&&(!b.payment||b.payment.state==='cancelled')){
 for(const [label,path] of [['Добавить кафе','/admin/cafe/?guestBill='+b.id+'#new'],['Добавить прокат','/admin/?guestBill='+b.id+'#work']]){const a=el('a',label);a.href=path;m.body.append(a);}
 if(b.totalCents){button(m.body,'Оплатить картой / QR · '+money(b.totalCents),()=>pay(false));button(m.body,'Получено наличными · '+money(b.totalCents),async()=>{if(await confirmCash('Деньги '+money(b.totalCents)+' получены? Чек пробейте вручную на CS50.'))await pay(true);});}
 button(m.body,'Отменить счёт',async()=>{const reason=prompt('Причина отмены всего неоплаченного счёта');if(!reason)return;busy=true;try{await api('guest-bills/cancel',{id:b.id,revision:b.revision,reason});m.d.close();document.dispatchEvent(new Event('station-updated'));}finally{busy=false;}});
 }
 async function pay(cash){busy=true;try{await api('guest-bills/pay',{id:b.id,revision:b.revision,cash,retryPaymentId:b.payment?.state==='cancelled'?b.payment.id:undefined});document.dispatchEvent(new Event('station-updated'));}finally{busy=false;}await draw();}
 }
 await draw();const timer=setInterval(()=>{if(m.d.open&&!document.hidden)draw().catch(e=>m.error.textContent=e.message);},5000);m.d.addEventListener('close',()=>clearInterval(timer));}
async function cash(){const m=modal('Наличные в кассе');m.d.classList.add('cash-balance-dialog');
 async function draw(){const s=await api('cash-ledger');m.body.replaceChildren();if(!s.shift){m.body.append(el('p','Рабочий день ещё не открыт.'));if(window.STARTWork?.openCash)button(m.body,'Открыть кассу',async()=>{await window.STARTWork.openCash();await draw();});return;}
 const balance=el('p',money(s.balanceCents));balance.className='cash-balance-amount';m.body.append(balance);
 const hint=el('p',s.unknownPayments?'Есть оплаты без указанного способа. Пересчитайте наличные для точного остатка.':'Расчётный остаток');hint.className='cash-balance-hint';m.body.append(hint);
 const actions=el('div');actions.className='cash-balance-actions';m.body.append(actions);
 for(const [kind,label] of [['deposit','Внести деньги'],['count','Пересчитать наличные']])button(actions,label,()=>{const f=modal(label),a=input(f.body,kind==='count'?'Фактически в кассе, ₽':'Сумма внесения, ₽'),why=input(f.body,'Причина / комментарий');a.inputMode='decimal';let body;button(f.body,'Сохранить',async()=>{if(!body)body={requestId:crypto.randomUUID(),kind,amountCents:cents(a.value),reason:why.value,version:s.version};try{await api('cash-ledger',body);}catch(e){if(e.status>=400&&e.status<500)body=null;throw e;}f.d.close();document.dispatchEvent(new Event('station-updated'));await draw();});});
 const details=el('details');details.append(el('summary','Расчёт и история'));details.append(el('p','Рабочий день: '+s.shift.day.split('-').reverse().join('.')));
 for(const [label,key] of [['На начало','openingCents'],['Наличные оплаты','salesCents'],['Внесения','depositsCents'],['Возвраты наличными','refundsCents'],['Изъятия','withdrawalsCents'],['Разница пересчётов','correctionsCents']])if(s[key]||key==='openingCents')details.append(el('p',label+': '+money(s[key])));
 for(const e of s.entries)details.append(el('p',new Date(e.created).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})+' · '+e.login+' · '+(e.kind==='count'?'Пересчёт':'Внесение')+' '+money(e.cents)+' · '+e.reason));m.body.append(details);button(details,'Обновить',draw);
 }
 await draw();}
function mount(){
 for(const selector of ['#issue-form','#checkout']){const f=document.querySelector(selector);if(!f||f.dataset.guestTools||selector==='#checkout'&&!document.querySelector('.cafe-integrated'))continue;f.dataset.guestTools='1';const id=Number(new URLSearchParams(location.search).get('guestBill'));if(id)f.dataset.guestBill=String(id);const tag=el('p');tag.className='guest-context';f.append(tag);button(f,'Получено наличными',async()=>{if(!f.reportValidity())return;if(!await confirmCash('Подтвердить получение наличных? Чек пробейте вручную на CS50.'))return;delete f.dataset.guestBill;f.dataset.cash='1';f.requestSubmit(selector==='#checkout'?document.querySelector('#checkout-button'):undefined);});const update=()=>{tag.textContent=f.dataset.guestBill?'Добавляется в счёт гостя №'+f.dataset.guestBill:'';if(normal)normal.hidden=!f.dataset.guestBill;};let normal;update();button(f,'В общий счёт / оплатить позже',async()=>{const b=await choose();if(!b)return;f.dataset.guestBill=String(b.id);delete f.dataset.cash;update();if(f.elements.name){if(!f.elements.name.value)f.elements.name.value=b.name;if(!f.elements.phone.value)f.elements.phone.value=b.phone;}f.requestSubmit(selector==='#checkout'?document.querySelector('#prepare-order'):undefined);});f.addEventListener('reset',()=>setTimeout(update,0));normal=button(f,'Обычный отдельный заказ',()=>{delete f.dataset.guestBill;delete f.dataset.cash;update();});update();}
}
window.STARTGuests={choose,show,cash,api};new MutationObserver(mount).observe(document.body,{childList:true,subtree:true});mount();
})();
